/**
 * Hand-owned lint overrides for the generated spartan/ui libs.
 *
 * Each `shared/ui/<name>/eslint.config.mjs` is generated by
 * `nx g @spartan-ng/cli:ui <name>` and enables `@nx/dependency-checks` on the
 * lib's package.json. The generator always emits the same peerDependencies
 * (@angular/common + @angular/core) regardless of what the component actually
 * imports, so that rule fails on ~28 libs. Fixing it would mean hand-editing
 * generated package.json files, which must stay regeneratable — so the rule is
 * turned off for these libs instead.
 *
 * Spread this LAST in every shared/ui lib config; in flat config the last
 * matching block wins, and the generated block that enables the rule comes
 * after the root config is spread.
 *
 * NOTE: re-running the generator for a component overwrites its
 * eslint.config.mjs and drops the spread below — re-apply it afterwards.
 */
export default [
  {
    files: ['**/*.json'],
    rules: {
      '@nx/dependency-checks': 'off',
    },
  },
  {
    // The generated carousel components use attribute selectors on a host
    // element (`button[hlmCarouselNext]`), which the generated config's
    // element-type component-selector rule rejects. Only matches in
    // shared/ui/carousel.
    files: ['**/hlm-carousel-next.ts', '**/hlm-carousel-previous.ts'],
    rules: {
      '@angular-eslint/component-selector': 'off',
    },
  },
];
